 function showLoginFormModal() { requireCaptcha = failedAttempts >= 2; const modal = document.createElement('div'); modal.className = 'modal-form'; modal.addEventListener('click', (e) => e.stopPropagation()); let html = `<div class="form-title"> Вход в BK-Bank</div><div id="loginError" class="error-text hidden"></div><input id="loginUsername" class="form-input" placeholder=" Никнейм или телефон"><input type="password" id="loginPassword" class="form-input" placeholder=" Пароль (учтите регистр)"><div id="capslock-warning" class="error-text hidden" style="color:#f39c12;"> CapsLock включен</div>`; if (requireCaptcha) { const ops = ['+', '-', '×']; const op = ops[Math.floor(Math.random() * ops.length)]; let n1, n2, ans; if (op === '+') { n1 = Math.floor(Math.random() * 20) + 1; n2 = Math.floor(Math.random() * 20) + 1; ans = n1 + n2; } else if (op === '-') { n1 = Math.floor(Math.random() * 20) + 11; n2 = Math.floor(Math.random() * 10) + 1; ans = n1 - n2; } else { n1 = Math.floor(Math.random() * 10) + 1; n2 = Math.floor(Math.random() * 10) + 1; ans = n1 * n2; } loginCaptchaAnswer = ans; html += `<div class="captcha-box"><div style="font-size:1rem; color:#888; margin-bottom:10px;"> Подтвердите, что вы человек</div><div class="captcha-question"><span class="captcha-emoji">🧮</span> ${n1} ${op} ${n2} = ?</div><input id="loginCaptcha" class="form-input" placeholder="Введите ответ" style="text-align:center;"></div>`; } html += `<div style="display:flex; align-items:center; gap:8px; margin:10px 0;"><input type="checkbox" id="rememberMeCheckbox" style="accent-color:#FFD700;"><label for="rememberMeCheckbox" style="color:#FFD700; font-size:0.9rem;">Запомнить меня</label></div>`; html += `<button class="gold-button" onclick="window.login()"> Войти</button><span class="text-link" onclick="window.openModal('register')"> Создать аккаунт</span><span class="text-link" style="color:#888 !important;" onclick="window.BKRecovery.showForgotPasswordModal()">Забыли пароль?</span>`; modal.innerHTML = html; document.body.appendChild(modal); const passwordInput = document.getElementById('loginPassword'); if (passwordInput) { passwordInput.addEventListener('keyup', function(event) { const warning = document.getElementById('capslock-warning'); if (warning) warning.classList.toggle('hidden', !event.getModifierState('CapsLock')); }); } }
