 function showAccountSwitcherModalContent() { const accounts = Object.keys(savedAccounts).filter(u => u !== currentUser && users[u]); const modal = document.createElement('div'); modal.className = 'modal-form'; modal.addEventListener('click', (e) => e.stopPropagation()); let html = `<div class="form-title"> Сменить аккаунт</div>`; if (accounts.length === 0) { html += `<p style="text-align:center; padding:20px; color:#888;">Нет сохраненных аккаунтов</p>`; } else { html += `<div style="display:flex; flex-direction:column; gap:8px;">`; accounts.forEach(acc => { const user = users[acc]; html += `<div class="saved-account-item" onclick="window.switchToAccount('${acc}')" style="cursor:pointer;"><img src="${user.avatar || 'assets/images/avatar.png'}" alt="${escapeHtml(user.name)}"><div class="saved-account-info"><div class="saved-account-name">${escapeHtml(user.name)}</div><div class="saved-account-username">@${escapeHtml(acc)}</div></div><button class="remove-account-btn" onclick="event.stopPropagation(); window.removeSavedAccountInModal('${acc}')">Удалить</button></div>`; }); html += `</div>`; } html += `<button class="gold-button" onclick="window.addNewAccount()">➕ Войти в другой аккаунт</button><button class="dark-button" onclick="window.closeModalAndGoToProfile()">Отмена</button>`; modal.innerHTML = html; document.body.appendChild(modal); }
