 function renderChart() { const container = document.getElementById('chart-bars'); if (!container) return; let trades = [...bktokTrades].reverse(); const periodMs = { '1H': 3600000, '6H': 21600000, '24H': 86400000, '1W': 604800000 }; const cutoff = Date.now() - (periodMs[chartPeriod] || 86400000); trades = trades.filter(t => new Date(t.time).getTime() > cutoff); if (trades.length === 0) { container.innerHTML = '<p style="text-align:center; padding:30px; color:#888;">Нет данных</p>'; document.getElementById('chart-open').textContent = '0'; document.getElementById('chart-high').textContent = '0'; document.getElementById('chart-low').textContent = '0'; document.getElementById('chart-change').textContent = '0%'; return; } const bars = []; const barCount = Math.min(12, trades.length); const step = Math.floor(trades.length / barCount) || 1; for (let i = 0; i < barCount; i++) { const slice = trades.slice(i * step, (i + 1) * step); if (!slice.length) continue; const prices = slice.map(t => t.price); bars.push({ open: prices[prices.length - 1], close: prices[0], high: Math.max(...prices), low: Math.min(...prices), isRed: prices[0] < prices[prices.length - 1] }); } const max = Math.max(...bars.map(b => b.high)); const min = Math.min(...bars.map(b => b.low)); const range = (max - min) || 1; container.innerHTML = bars.map(b => { const height = ((b.close - min) / range) * 120 + 40; return `<div class="chart-bar-wrapper"><div class="chart-bar ${b.isRed ? 'red' : ''}" style="height:${height}px;" title="O:${b.open.toFixed(2)} H:${b.high.toFixed(2)} L:${b.low.toFixed(2)} C:${b.close.toFixed(2)}"></div><div class="chart-bar-value">${b.close.toFixed(2)}</div></div>`; }).join(''); const first = bars[0]?.open || 0; const last = bars[bars.length - 1]?.close || 0; const change = last - first; const percent = first ? ((change / first) * 100).toFixed(2) : 0; document.getElementById('chart-open').textContent = first.toFixed(2); document.getElementById('chart-high').textContent = max.toFixed(2); document.getElementById('chart-low').textContent = min.toFixed(2); const changeEl = document.getElementById('chart-change'); changeEl.textContent = (change >= 0 ? '+' : '') + percent + '%'; changeEl.className = 'chart-stat-value ' + (change >= 0 ? 'positive' : 'negative'); }
 function updateOrderBook() { let buyHtml = ''; let sellHtml = ''; const buyOrders = [...bktokOrders.buy].sort((a, b) => b.price - a.price); const sellOrders = [...bktokOrders.sell].sort((a, b) => a.price - b.price); buyOrders.slice(0, 8).forEach(o => { buyHtml += `<div style="display:flex; justify-content:space-between; padding:8px; border-bottom:1px solid rgba(255,255,255,0.05);"><span>${o.amount.toFixed(2)} BK</span><span style="color:#4ade80;">${o.price.toFixed(2)} ₽</span></div>`; }); sellOrders.slice(0, 8).forEach(o => { sellHtml += `<div style="display:flex; justify-content:space-between; padding:8px; border-bottom:1px solid rgba(255,255,255,0.05);"><span>${o.amount.toFixed(2)} BK</span><span style="color:#ff5e5e;">${o.price.toFixed(2)} ₽</span></div>`; }); const buyEl = document.getElementById('buy-orders'); const sellEl = document.getElementById('sell-orders'); if (buyEl) buyEl.innerHTML = buyHtml || '<p style="color:#888; padding:10px;">Нет заявок</p>'; if (sellEl) sellEl.innerHTML = sellHtml || '<p style="color:#888; padding:10px;">Нет заявок</p>'; const myOrders = [...bktokOrders.buy, ...bktokOrders.sell].filter(o => o.user === currentUser); const myOrdersEl = document.getElementById('my-orders'); if (myOrdersEl) { myOrdersEl.innerHTML = myOrders.length ? myOrders.map(o => `<div style="display:flex; justify-content:space-between; padding:8px; background:rgba(255,215,0,0.05); margin-bottom:5px; border-radius:8px;"><span>${o.side === 'buy' ? '🟢 Покупка' : '🔴 Продажа'} ${o.amount.toFixed(2)} BK @ ${o.price.toFixed(2)} ₽</span><button onclick="cancelOrder('${o.id}')" style="background:transparent; border:none; color:#ff5e5e; cursor:pointer;">✕</button></div>`).join('') : '<p style="color:#888;">Нет активных ордеров</p>'; } }
 function renderTradeHistory() { const container = document.getElementById('trade-history'); if (!container) return; const userTrades = bktokTrades.filter(t => t.buyer === currentUser || t.seller === currentUser).slice(-10).reverse(); container.innerHTML = userTrades.length ? userTrades.map(t => `<div style="padding:8px; border-bottom:1px solid rgba(255,255,255,0.05);"><span style="color:${t.buyer === currentUser ? '#4ade80' : '#ff5e5e'};">${t.buyer === currentUser ? 'Покупка' : 'Продажа'}</span> ${t.amount.toFixed(2)} BK @ ${t.price.toFixed(2)} ₽ <small>${new Date(t.time).toLocaleTimeString()}</small></div>`).join('') : '<p style="color:#888;">Нет сделок</p>'; }
 function createOrder(side) { const priceEl = document.getElementById('order-price'); const amountEl = document.getElementById('order-amount'); const price = parseFloat(priceEl.value); const amount = parseFloat(amountEl.value); if (!price || !amount || price <= 0 || amount <= 0) { alert('Введите корректные положительные цену и количество'); return; } const fee = amount * price * 0.001; const totalCost = amount * price + fee; const available = getAvailableBalance(currentUser); if (side === 'buy') { if (available < totalCost) { alert(`Недостаточно средств. Доступно: ${available.toFixed(2)} BK`); return; } if (!freezeBalance(currentUser, totalCost)) { alert('Ошибка заморозки средств'); return; } } else { if (available < amount) { alert(`Недостаточно BK. Доступно: ${available.toFixed(2)} BK`); return; } if (!freezeBalance(currentUser, amount)) { alert('Ошибка заморозки средств'); return; } } const order = { id: crypto.randomUUID ? crypto.randomUUID() : Date.now() + '-' + Math.random().toString(36).substr(2, 9), user: currentUser, side: side, price: price, amount: amount, created: Date.now() }; bktokOrders[side].push(order); sendOrderToDiscord(order); realSetItem('public_bktokOrders', JSON.stringify(bktokOrders)); matchOrders(); loadBKtok(); }
