 const tasks = [ { id: 'daily', name: 'Ежедневный вход', reward: 10, cooldown: 86400000 }, { id: 'profile', name: 'Заполнить профиль', reward: 50, once: true }, { id: 'avatar', name: 'Установить аватар', reward: 30, once: true }, { id: 'trade', name: 'Совершить сделку', reward: 20, cooldown: 3600000 } ];
 function renderTasks() { if (!currentUser) return; if (!userTasks[currentUser]) userTasks[currentUser] = {}; const container = document.getElementById('tasks-container'); container.innerHTML = tasks.map(task => { const completed = userTasks[currentUser][task.id]; const canComplete = !completed || (task.cooldown && Date.now() - completed > task.cooldown); return `<div class="task-item ${!canComplete ? 'completed' : ''}" ${canComplete ? `onclick="completeTask('${task.id}')"` : ''}><strong>${escapeHtml(task.name)}</strong><div style="color:#FFD700; margin-top:8px;">+${task.reward} BK</div></div>`; }).join(''); }
