 function renderAISupport() { const container = document.getElementById('support-container'); if (!currentUser) { container.innerHTML = '<p style="text-align:center; padding:20px;"> Войдите, чтобы задать вопрос</p>'; return; } if (!allSupportChats[currentUser]) { allSupportChats[currentUser] = [{ from: 'ai', text: '👋 Здравствуйте! Я нейросеть BK-Bank. Могу помочь с балансом, картами, токенами.', time: new Date().toISOString() }]; } let html = `<div class="chat-messages" id="ai-chat-messages"></div><div class="chat-input-area"><input id="ai-chat-input" class="chat-input" placeholder="Задайте вопрос..."><button class="chat-send-btn" onclick="sendAIMessage()">Отправить</button></div>`; container.innerHTML = html; loadAIMessages(); }
