 function renderPrivateChats() { const container = document.getElementById('chats-container'); const myChats = Object.keys(privateChats); let html = `<div class="support-panel"><div class="users-list"><h4>Чаты</h4><button class="gold-button" onclick="startNewChat()" style="margin-bottom:10px;">+ Новый</button>`; myChats.forEach(id => { const other = id.split('-').find(u => u !== currentUser); html += `<div class="user-item" onclick="openPrivateChat('${id}')"><strong>${escapeHtml(other)}</strong></div>`; }); html += `</div><div class="chat-area">`; if (selectedPrivateChat) { const other = selectedPrivateChat.split('-').find(u => u !== currentUser); html += `<h4>Чат с ${escapeHtml(other)}</h4><div class="chat-messages" id="private-chat-messages"></div><div class="chat-input-area"><input id="private-chat-input" class="chat-input" placeholder="Сообщение..."><button class="chat-send-btn" onclick="sendPrivateMessage()">Отправить</button></div>`; } else { html += `<p>Выберите чат</p>`; } html += `</div></div>`; container.innerHTML = html; if (selectedPrivateChat) loadPrivateChatMessages(); }
